import "server-only";
import { z } from "zod";
import type { Prisma } from "@/generated/prisma/client";
import {
  generateSchedule,
  invoiceStatus,
  type InvoiceKind,
  type InvoiceStatus,
  type ScheduledInvoice,
} from "@/lib/billing";
import {
  calendarDateFromDb,
  calendarDateToDb,
  toMalaysiaIso,
  todayInMalaysia,
} from "@/lib/dates";
import { toSafeNumber } from "@/lib/money";
import {
  isUuid,
  requireManager,
  requireMember,
  requireVisibleLease,
} from "../access";
import { writeAudit } from "../allocation";
import type { Actor } from "../auth";
import { pgErrorCode } from "../db-errors";
import { badRequest, conflict, notFound } from "../http";
import { prisma } from "../prisma";

// Lease creation and the read models built on leases (lease detail, leases
// list, dashboard). Services take an Actor and authorize themselves; routes,
// Server Actions and the seed script all go through here.

const createLeaseSchema = z.object({
  unitId: z.string(),
  tenantId: z.string(),
  startDate: z.string(),
  endDate: z.string(),
  monthlyRentSen: z.int().positive(),
  depositSen: z.int().nonnegative(),
});

const PAGE_SIZE = 20;
// 100 years of monthly invoices. Guards against a typo (year 9999) inserting
// ~100k rows in one request; no real lease comes close.
const MAX_SCHEDULE_LENGTH = 1201;
const TRANSACTION_OPTIONS = { maxWait: 10000, timeout: 20000 };
const EXCLUSION_VIOLATION = "23P01";
const OVERLAP_MESSAGE = "The unit already has a lease overlapping these dates";

const paymentMethods = ["cash", "bank_transfer", "online"] as const;
const paymentStatuses = [
  "pending_verification",
  "approved",
  "rejected",
  "voided",
] as const;

export type CreateLeaseInput = z.input<typeof createLeaseSchema>;

export type LeaseDetail = {
  lease: {
    id: string;
    unitId: string;
    tenantId: string;
    startDate: string;
    endDate: string;
    monthlyRentSen: number;
    depositSen: number;
  };
  invoices: {
    id: string;
    kind: InvoiceKind;
    periodIndex: number | null;
    periodStart: string | null;
    periodEnd: string | null;
    dueDate: string;
    amountSen: number;
    paidSen: number;
    status: InvoiceStatus;
  }[];
  payments: {
    id: string;
    amountSen: number;
    unappliedSen: number;
    method: "cash" | "bank_transfer" | "online";
    status: "pending_verification" | "approved" | "rejected" | "voided";
    receivedAt: string;
  }[];
};

export type LeaseListRow = {
  id: string;
  unitName: string;
  tenantName: string;
  startDate: string;
  endDate: string;
  monthlyRentSen: number;
  depositSen: number;
};

export type LeaseListQuery = { q?: string; page?: number };

export type LeaseList = {
  rows: LeaseListRow[];
  total: number;
  pageSize: number;
};

export type DashboardStats = { overdueCount: number };

type OverdueCandidateRow = {
  due_date: Date;
  amount_sen: bigint;
  paid_sen: bigint;
};

const asPaymentMethod = (
  value: string,
): LeaseDetail["payments"][number]["method"] => {
  const method = paymentMethods.find((m) => m === value);
  if (!method) {
    throw new Error(`Unknown payment method in database: ${value}`);
  }
  return method;
};

const asPaymentStatus = (
  value: string,
): LeaseDetail["payments"][number]["status"] => {
  const status = paymentStatuses.find((s) => s === value);
  if (!status) {
    throw new Error(`Unknown payment status in database: ${value}`);
  }
  return status;
};

const asInvoiceKind = (value: string): InvoiceKind => {
  if (value !== "deposit" && value !== "rent") {
    throw new Error(`Unknown invoice kind in database: ${value}`);
  }
  return value;
};

const scheduleOrBadRequest = (
  input: z.output<typeof createLeaseSchema>,
): ScheduledInvoice[] => {
  let schedule: ScheduledInvoice[];
  try {
    schedule = generateSchedule(input);
  } catch (error) {
    throw badRequest(error instanceof Error ? error.message : "Invalid lease");
  }
  if (schedule.length > MAX_SCHEDULE_LENGTH) {
    throw badRequest("Lease is too long (more than 100 years)");
  }
  return schedule;
};

/**
 * Manager only. Stores the lease and exactly generateSchedule's invoices, all
 * or nothing. Overlap safety: the unit row is locked first, so concurrent
 * creates on one unit queue up and the pre-check sees the earlier lease; the
 * leases_no_overlap exclusion constraint is the backstop (23P01 -> 409).
 */
export const createLease = async (
  actor: Actor,
  input: unknown,
): Promise<{ id: string }> => {
  requireManager(actor);
  const data = createLeaseSchema.parse(input);
  const schedule = scheduleOrBadRequest(data);
  // IDs in the body are untrusted: another org's unit/tenant is "not found".
  if (!isUuid(data.unitId) || !isUuid(data.tenantId)) {
    throw notFound();
  }
  const startDate = calendarDateToDb(data.startDate);
  const endDate = calendarDateToDb(data.endDate);

  try {
    return await prisma.$transaction(async (tx) => {
      const units = await tx.$queryRaw<{ id: string }[]>`
        SELECT id FROM public.units
         WHERE id = ${data.unitId}::uuid AND org_id = ${actor.orgId}::uuid
           FOR UPDATE`;
      if (units.length === 0) {
        throw notFound();
      }
      const tenant = await tx.tenants.findFirst({
        where: { id: data.tenantId, org_id: actor.orgId },
        select: { id: true },
      });
      if (!tenant) {
        throw notFound();
      }
      // Both ends inclusive: [a, b] and [c, d] overlap iff a <= d and c <= b.
      const overlapping = await tx.leases.findFirst({
        where: {
          unit_id: data.unitId,
          start_date: { lte: endDate },
          end_date: { gte: startDate },
        },
        select: { id: true },
      });
      if (overlapping) {
        throw conflict(OVERLAP_MESSAGE);
      }

      const lease = await tx.leases.create({
        data: {
          org_id: actor.orgId,
          unit_id: data.unitId,
          tenant_id: data.tenantId,
          start_date: startDate,
          end_date: endDate,
          monthly_rent_sen: BigInt(data.monthlyRentSen),
          deposit_sen: BigInt(data.depositSen),
          created_by: actor.userId,
        },
        select: { id: true },
      });
      await tx.invoices.createMany({
        data: schedule.map((invoice): Prisma.invoicesCreateManyInput => ({
          org_id: actor.orgId,
          lease_id: lease.id,
          kind: invoice.kind,
          period_index: invoice.periodIndex,
          period_start:
            invoice.periodStart === null
              ? null
              : calendarDateToDb(invoice.periodStart),
          period_end:
            invoice.periodEnd === null
              ? null
              : calendarDateToDb(invoice.periodEnd),
          due_date: calendarDateToDb(invoice.dueDate),
          amount_sen: BigInt(invoice.amountSen),
        })),
      });
      await writeAudit(tx, {
        orgId: actor.orgId,
        actorId: actor.userId,
        action: "lease.created",
        entityId: lease.id,
        details: {
          unitId: data.unitId,
          tenantId: data.tenantId,
          startDate: data.startDate,
          endDate: data.endDate,
          monthlyRentSen: data.monthlyRentSen,
          depositSen: data.depositSen,
          invoiceCount: schedule.length,
        },
      });
      return { id: lease.id };
    }, TRANSACTION_OPTIONS);
  } catch (error) {
    if (pgErrorCode(error) === EXCLUSION_VIOLATION) {
      throw conflict(OVERLAP_MESSAGE);
    }
    throw error;
  }
};

/**
 * GET /api/leases/:leaseId. Invoices in allocation order (due date, deposit
 * before rent, period index); paid = sum of allocations; status computed now.
 */
export const getLeaseDetail = async (
  actor: Actor,
  leaseId: string,
  now: Date = new Date(),
): Promise<LeaseDetail> => {
  const lease = await requireVisibleLease(actor, leaseId);
  const [invoices, payments] = await Promise.all([
    prisma.invoices.findMany({
      where: { lease_id: lease.id },
      // kind ASC puts 'deposit' before 'rent' (alphabetical), which is the
      // brief's "deposit before rent" tie-break on the same due date.
      orderBy: [{ due_date: "asc" }, { kind: "asc" }, { period_index: "asc" }],
      include: { payment_allocations: { select: { amount_sen: true } } },
    }),
    prisma.payments.findMany({
      where: { lease_id: lease.id },
      orderBy: [{ received_at: "asc" }, { created_at: "asc" }],
    }),
  ]);

  return {
    lease: {
      id: lease.id,
      unitId: lease.unit_id,
      tenantId: lease.tenant_id,
      startDate: calendarDateFromDb(lease.start_date),
      endDate: calendarDateFromDb(lease.end_date),
      monthlyRentSen: toSafeNumber(lease.monthly_rent_sen),
      depositSen: toSafeNumber(lease.deposit_sen),
    },
    invoices: invoices.map((invoice) => {
      const paidSen = toSafeNumber(
        invoice.payment_allocations.reduce((sum, a) => sum + a.amount_sen, 0n),
      );
      const amountSen = toSafeNumber(invoice.amount_sen);
      const dueDate = calendarDateFromDb(invoice.due_date);
      return {
        id: invoice.id,
        kind: asInvoiceKind(invoice.kind),
        periodIndex: invoice.period_index,
        periodStart:
          invoice.period_start === null
            ? null
            : calendarDateFromDb(invoice.period_start),
        periodEnd:
          invoice.period_end === null
            ? null
            : calendarDateFromDb(invoice.period_end),
        dueDate,
        amountSen,
        paidSen,
        status: invoiceStatus({ dueDate, amountSen, paidSen }, now),
      };
    }),
    payments: payments.map((payment) => ({
      id: payment.id,
      amountSen: toSafeNumber(payment.amount_sen),
      unappliedSen: toSafeNumber(payment.unapplied_sen),
      method: asPaymentMethod(payment.method),
      status: asPaymentStatus(payment.status),
      receivedAt: toMalaysiaIso(payment.received_at),
    })),
  };
};

/**
 * Leases list for the UI: members see their organization's leases, a tenant
 * sees their own. Server-side search on unit or tenant name, 20 per page.
 */
export const listLeases = async (
  actor: Actor,
  query: LeaseListQuery = {},
): Promise<LeaseList> => {
  const q = query.q?.trim() ?? "";
  const page =
    query.page !== undefined &&
    Number.isSafeInteger(query.page) &&
    query.page > 0
      ? query.page
      : 1;
  const where: Prisma.leasesWhereInput = {
    org_id: actor.orgId,
    ...(actor.kind === "tenant" ? { tenant_id: actor.tenantId } : {}),
    ...(q
      ? {
          OR: [
            { units: { name: { contains: q, mode: "insensitive" } } },
            { tenants: { full_name: { contains: q, mode: "insensitive" } } },
          ],
        }
      : {}),
  };
  const [rows, total] = await Promise.all([
    prisma.leases.findMany({
      where,
      orderBy: [{ start_date: "desc" }, { id: "asc" }],
      skip: (page - 1) * PAGE_SIZE,
      take: PAGE_SIZE,
      include: {
        units: { select: { name: true } },
        tenants: { select: { full_name: true } },
      },
    }),
    prisma.leases.count({ where }),
  ]);
  return {
    rows: rows.map((lease) => ({
      id: lease.id,
      unitName: lease.units.name,
      tenantName: lease.tenants.full_name,
      startDate: calendarDateFromDb(lease.start_date),
      endDate: calendarDateFromDb(lease.end_date),
      monthlyRentSen: toSafeNumber(lease.monthly_rent_sen),
      depositSen: toSafeNumber(lease.deposit_sen),
    })),
    total,
    pageSize: PAGE_SIZE,
  };
};

/**
 * Dashboard numbers for staff and managers. The overdue count uses
 * invoiceStatus (statuses are never stored); SQL only pre-filters invoices
 * that are not fully paid and due before today's Malaysia date.
 */
export const dashboardStats = async (
  actor: Actor,
  now: Date = new Date(),
): Promise<DashboardStats> => {
  requireMember(actor);
  const today = todayInMalaysia(now);
  const candidates = await prisma.$queryRaw<OverdueCandidateRow[]>`
    SELECT i.due_date, i.amount_sen,
           coalesce(sum(a.amount_sen), 0)::bigint AS paid_sen
      FROM public.invoices i
      LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
     WHERE i.org_id = ${actor.orgId}::uuid
       AND i.due_date < ${today}::date
     GROUP BY i.id
    HAVING coalesce(sum(a.amount_sen), 0) < i.amount_sen`;
  const overdueCount = candidates.filter(
    (row) =>
      invoiceStatus(
        {
          dueDate: calendarDateFromDb(row.due_date),
          amountSen: toSafeNumber(BigInt(row.amount_sen)),
          paidSen: toSafeNumber(BigInt(row.paid_sen)),
        },
        now,
      ) === "overdue",
  ).length;
  return { overdueCount };
};
import "server-only";
import { z } from "zod";
import type { payments } from "@/generated/prisma/client";
import { toSafeNumber } from "@/lib/money";
import {
  requireManager,
  requireMember,
  requireVisibleLease,
  requireVisiblePayment,
} from "../access";
import {
  allocatePayment,
  leaseTotals,
  lockLease,
  writeAudit,
  type Tx,
} from "../allocation";
import type { Actor } from "../auth";
import { pgErrorCode } from "../db-errors";
import { badRequest, conflict, notFound, unprocessable } from "../http";
import { prisma } from "../prisma";
import { removeSlip, signedSlipUrl, uploadSlip } from "../slips";

// Manual payments (cash, bank transfer) and the manager decisions on them.
//
// Concurrency: every transaction here locks the lease row FIRST (lockLease),
// then re-reads whatever it decides on. Two staff recording at once, or two
// managers approving at once, therefore run one after the other on that
// lease, and the second sees the first's committed rows: the cap cannot be
// exceeded together and a payment cannot be approved (allocated) twice.
//
// Check order in every entry point: 404 (not visible) -> 403 (role) ->
// 400 (input) -> 409 (state) / 422 (amount). 401 is the route's job.

const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;
const TRANSACTION_OPTIONS = { maxWait: 10000, timeout: 20000 };
const FK_VIOLATION = "23503";
const UNIQUE_VIOLATION = "23505";

const recordPaymentSchema = z.object({
  amountSen: z.int().positive(),
  method: z.enum(["cash", "bank_transfer"]),
  // ISO 8601 with an explicit offset (Z or ±hh:mm); a bare local time is
  // ambiguous on a UTC server, so it is refused rather than guessed.
  receivedAt: z.union([z.iso.datetime({ offset: true }), z.date()]),
  slipPath: z.string().min(1).optional(),
});

const reasonSchema = z.object({
  reason: z.string().trim().min(5, "Reason must be at least 5 characters"),
});

export type RecordPaymentInput = z.input<typeof recordPaymentSchema>;
export type ReasonInput = z.input<typeof reasonSchema>;
export type PaymentStatus =
  "pending_verification" | "approved" | "rejected" | "voided";
export type RecordPaymentResult = { id: string; status: PaymentStatus };
export type DecisionResult = { status: PaymentStatus };
export type SlipInput = Omit<RecordPaymentInput, "slipPath" | "method"> & {
  method: "cash" | "bank_transfer";
};

const toInstant = (value: string | Date): Date => {
  const instant = typeof value === "string" ? new Date(value) : value;
  if (Number.isNaN(instant.getTime())) {
    throw badRequest("receivedAt: Invalid date-time");
  }
  return instant;
};

// Re-reads the payment under a row lock, after the lease lock is held.
const lockPayment = async (tx: Tx, paymentId: string): Promise<payments> => {
  await tx.$queryRaw`
    SELECT id FROM public.payments WHERE id = ${paymentId}::uuid FOR UPDATE`;
  const payment = await tx.payments.findUnique({ where: { id: paymentId } });
  if (!payment) {
    throw notFound();
  }
  return payment;
};

const asStatus = (status: string): PaymentStatus => {
  if (
    status !== "pending_verification" &&
    status !== "approved" &&
    status !== "rejected" &&
    status !== "voided"
  ) {
    throw new Error(`Unknown payment status in database: ${status}`);
  }
  return status;
};

/**
 * POST /api/leases/:leaseId/payments. Staff and managers only. A manager's
 * payment is approved (and allocated) at once; a staff payment waits as
 * pending_verification. Capped at the lease's remaining balance minus what is
 * already pending.
 */
export const recordPayment = async (
  actor: Actor,
  leaseId: string,
  input: unknown,
  now: Date = new Date(),
): Promise<RecordPaymentResult> => {
  const lease = await requireVisibleLease(actor, leaseId);
  requireMember(actor);
  const data = recordPaymentSchema.parse(input);
  const receivedAt = toInstant(data.receivedAt);
  if (receivedAt.getTime() > now.getTime() + MAX_CLOCK_SKEW_MS) {
    throw badRequest("receivedAt cannot be in the future");
  }
  if (data.method === "bank_transfer") {
    if (!data.slipPath) {
      throw badRequest("slipPath: A bank transfer needs a slip");
    }
    if (!data.slipPath.startsWith(`${lease.org_id}/`)) {
      throw badRequest("slipPath: Slip must be in the organization's folder");
    }
  } else if (data.slipPath !== undefined) {
    throw badRequest("slipPath: Only a bank transfer has a slip");
  }

  const approveNow = actor.role === "manager";
  try {
    return await prisma.$transaction(async (tx) => {
      await lockLease(tx, lease.id);
      const totals = await leaseTotals(tx, lease.id);
      const cap = totals.invoicedSen - totals.allocatedSen - totals.pendingSen;
      if (BigInt(data.amountSen) > cap) {
        throw unprocessable(
          `Amount exceeds the remaining balance (max ${cap > 0n ? cap.toString() : "0"} sen)`,
        );
      }
      const decidedAt = new Date();
      const payment = await tx.payments.create({
        data: {
          org_id: lease.org_id,
          lease_id: lease.id,
          amount_sen: BigInt(data.amountSen),
          method: data.method,
          status: approveNow ? "approved" : "pending_verification",
          received_at: receivedAt,
          slip_path: data.slipPath ?? null,
          recorded_by: actor.userId,
          decided_by: approveNow ? actor.userId : null,
          decided_at: approveNow ? decidedAt : null,
        },
        select: { id: true, status: true },
      });
      await writeAudit(tx, {
        orgId: lease.org_id,
        actorId: actor.userId,
        action: "payment.recorded",
        entityId: payment.id,
        details: {
          leaseId: lease.id,
          amountSen: data.amountSen,
          method: data.method,
          receivedAt: receivedAt.toISOString(),
          slipPath: data.slipPath ?? null,
        },
      });
      if (approveNow) {
        await allocatePayment(tx, payment.id);
        await writeAudit(tx, {
          orgId: lease.org_id,
          actorId: actor.userId,
          action: "payment.approved",
          entityId: payment.id,
          details: {
            leaseId: lease.id,
            amountSen: data.amountSen,
            onRecord: true,
          },
        });
      }
      return { id: payment.id, status: asStatus(payment.status) };
    }, TRANSACTION_OPTIONS);
  } catch (error) {
    const code = pgErrorCode(error);
    // payments_slip_exists trigger: the file is not in the bucket.
    if (code === FK_VIOLATION) {
      throw badRequest("slipPath: Slip file not found");
    }
    // payments.slip_path is unique: one slip backs one payment.
    if (code === UNIQUE_VIOLATION) {
      throw badRequest("slipPath: Slip is already used by another payment");
    }
    throw error;
  }
};

/**
 * UI path for a bank transfer: upload the slip, record the payment, and
 * remove the uploaded file if recording fails (the brief: no file is left
 * behind). Cash goes straight to recordPayment.
 */
export const recordPaymentWithSlip = async (
  actor: Actor,
  leaseId: string,
  input: SlipInput,
  slip: File | null,
): Promise<RecordPaymentResult> => {
  const lease = await requireVisibleLease(actor, leaseId);
  requireMember(actor);
  if (input.method === "cash") {
    return recordPayment(actor, lease.id, input);
  }
  if (!slip) {
    throw badRequest("slip: A bank transfer needs a slip");
  }
  const slipPath = await uploadSlip(lease.org_id, lease.id, slip);
  try {
    return await recordPayment(actor, lease.id, { ...input, slipPath });
  } catch (error) {
    await removeSlip(slipPath).catch(() => undefined);
    throw error;
  }
};

/**
 * Manager only. Re-checks the amount against the remaining balance at this
 * moment (invoiced - allocated); if it no longer fits, 422 and it stays
 * pending. Approving twice at once: the second waits on the lease lock, then
 * sees 'approved' and gets 409, so allocation happens once.
 */
export const approvePayment = async (
  actor: Actor,
  paymentId: string,
): Promise<DecisionResult> => {
  const visible = await requireVisiblePayment(actor, paymentId);
  requireManager(actor);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, visible.lease_id);
    const payment = await lockPayment(tx, visible.id);
    if (payment.status !== "pending_verification") {
      throw conflict(`Payment is ${payment.status}, not pending_verification`);
    }
    const totals = await leaseTotals(tx, payment.lease_id);
    const remaining = totals.invoicedSen - totals.allocatedSen;
    if (payment.amount_sen > remaining) {
      throw unprocessable(
        `Amount exceeds the remaining balance (${remaining > 0n ? remaining.toString() : "0"} sen)`,
      );
    }
    await tx.payments.update({
      where: { id: payment.id },
      data: {
        status: "approved",
        decided_by: actor.userId,
        decided_at: new Date(),
      },
    });
    await allocatePayment(tx, payment.id);
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: actor.userId,
      action: "payment.approved",
      entityId: payment.id,
      details: {
        leaseId: payment.lease_id,
        amountSen: toSafeNumber(payment.amount_sen),
      },
    });
    return { status: "approved" as const };
  }, TRANSACTION_OPTIONS);
};

/** Manager only. pending_verification -> rejected, with a reason (>= 5 chars). */
export const rejectPayment = async (
  actor: Actor,
  paymentId: string,
  input: unknown,
): Promise<DecisionResult> => {
  const visible = await requireVisiblePayment(actor, paymentId);
  requireManager(actor);
  const { reason } = reasonSchema.parse(input);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, visible.lease_id);
    const payment = await lockPayment(tx, visible.id);
    if (payment.status !== "pending_verification") {
      throw conflict(`Payment is ${payment.status}, not pending_verification`);
    }
    await tx.payments.update({
      where: { id: payment.id },
      data: {
        status: "rejected",
        decision_reason: reason,
        decided_by: actor.userId,
        decided_at: new Date(),
      },
    });
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: actor.userId,
      action: "payment.rejected",
      entityId: payment.id,
      details: { leaseId: payment.lease_id, reason },
    });
    return { status: "rejected" as const };
  }, TRANSACTION_OPTIONS);
};

/**
 * Manager only. approved -> voided, with a reason; removes this payment's
 * allocations only. Other payments are not touched and nothing is
 * re-allocated (in particular, no other payment's unapplied_sen moves in to
 * fill the reopened invoices — see DECISIONS.md).
 */
export const voidPayment = async (
  actor: Actor,
  paymentId: string,
  input: unknown,
): Promise<DecisionResult> => {
  const visible = await requireVisiblePayment(actor, paymentId);
  requireManager(actor);
  const { reason } = reasonSchema.parse(input);
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, visible.lease_id);
    const payment = await lockPayment(tx, visible.id);
    if (payment.status !== "approved") {
      throw conflict(`Payment is ${payment.status}, not approved`);
    }
    // Status first: the allocation trigger only allows deletes once voided.
    await tx.payments.update({
      where: { id: payment.id },
      data: {
        status: "voided",
        decision_reason: reason,
        decided_by: actor.userId,
        decided_at: new Date(),
      },
    });
    const removed = await tx.payment_allocations.deleteMany({
      where: { payment_id: payment.id },
    });
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: actor.userId,
      action: "payment.voided",
      entityId: payment.id,
      details: {
        leaseId: payment.lease_id,
        amountSen: toSafeNumber(payment.amount_sen),
        reason,
        allocationsRemoved: removed.count,
      },
    });
    return { status: "voided" as const };
  }, TRANSACTION_OPTIONS);
};

/**
 * A 60-second signed URL for a payment's slip. Staff and managers of the
 * payment's organization only (tenants cannot read slips: 403); null when the
 * payment has no slip.
 */
export const paymentSlipUrl = async (
  actor: Actor,
  paymentId: string,
): Promise<string | null> => {
  const payment = await requireVisiblePayment(actor, paymentId);
  requireMember(actor);
  return payment.slip_path ? signedSlipUrl(payment.slip_path) : null;
};

