    tag,
    orgA: orgA.id,
    orgB: orgB.id,
    units,
    tenants: { a1: tA1, a2: tA2, b1: tB1 },
    users: {
      managerA,
      staffA,
      tenantA1,
      tenantA2,
      managerB,
      tenantB1,
      metaManager,
    },
    actors,
    leases: { l1: l1.id, l2: l2.id, future: future.id, lb: lb.id },
    payments: {
      l1Approved: l1Approved.id,
      l1Pending: l1Pending.id,
      lbApproved: lbApproved.id,
    },
    bills: { l1: billL1.billId, lb: billLb.billId },
    revokedToken,
  };
